import http from 'node:http';
/* a stand-in for Ollama: lists one model and streams a JSON answer the way /api/chat does */
function fakeOllama(){return new Promise(res=>{const got=[];const s=http.createServer((q,r)=>{r.setHeader('Access-Control-Allow-Origin','*');r.setHeader('Access-Control-Allow-Headers','*');if(q.method==='OPTIONS'){r.end();return}
  if(q.url==='/api/tags'){r.end(JSON.stringify({models:[{name:'qwen-test:1b'}]}));return}
  if(q.url==='/api/chat'){let b='';q.on('data',d=>b+=d);q.on('end',async()=>{got.push(JSON.parse(b));const t=JSON.stringify({reply:'Added a pantry.',commands:[{do:'room',name:'AI pantry',x:80000,y:0,w:4000,h:3000}]});r.setHeader('Content-Type','application/x-ndjson');for(let i=0;i<t.length;i+=40){r.write(JSON.stringify({message:{role:'assistant',content:t.slice(i,i+40)},done:false})+'\n');await new Promise(z=>setTimeout(z,5))}r.end(JSON.stringify({done:true})+'\n')});return}
  r.statusCode=404;r.end()});s.listen(0,'127.0.0.1',()=>res({url:'http://127.0.0.1:'+s.address().port,got,close:()=>s.close()}))})}
/* a stand-in for Anthropic's Messages API: lists models and streams a forced tool call as server-sent events */
function fakeAnthropic(){return new Promise(res=>{const got=[];const s=http.createServer((q,r)=>{r.setHeader('Access-Control-Allow-Origin','*');r.setHeader('Access-Control-Allow-Headers','*');r.setHeader('Access-Control-Allow-Methods','GET,POST,OPTIONS');if(q.method==='OPTIONS'){r.end();return}
  const key=q.headers['x-api-key'];if(key!=='sk-test'){r.statusCode=401;r.end(JSON.stringify({type:'error',error:{type:'authentication_error',message:'invalid x-api-key'}}));return}
  if(q.url.startsWith('/v1/models')){r.end(JSON.stringify({data:[{id:'claude-opus-5-5'},{id:'claude-sonnet-5-5'}]}));return}
  if(q.url==='/v1/messages'){let b='';q.on('data',d=>b+=d);q.on('end',async()=>{got.push({h:q.headers,b:JSON.parse(b)});r.setHeader('Content-Type','text/event-stream');const ev=(t,d)=>r.write(`event: ${t}\ndata: ${JSON.stringify(Object.assign({type:t},d))}\n\n`);
    ev('message_start',{message:{id:'m1',role:'assistant',content:[]}});ev('content_block_start',{index:0,content_block:{type:'tool_use',id:'t1',name:'apply_commands',input:{}}});
    const t=JSON.stringify({reply:'Added a lobby.',commands:[{do:'room',name:'Claude lobby',x:90000,y:0,w:6000,h:5000}]});for(let i=0;i<t.length;i+=30){ev('content_block_delta',{index:0,delta:{type:'input_json_delta',partial_json:t.slice(i,i+30)}});await new Promise(z=>setTimeout(z,5))}
    ev('content_block_stop',{index:0});ev('message_delta',{delta:{stop_reason:'tool_use'}});ev('message_stop',{});r.end()});return}
  r.statusCode=404;r.end()});s.listen(0,'127.0.0.1',()=>res({url:'http://127.0.0.1:'+s.address().port,got,close:()=>s.close()}))})}
/* an Ollama stand-in for the agent loop: the first answer has two overlapping rooms and a desk outside them; when the problems come back it sends the fixes */
function fakeLoop(){return new Promise(res=>{const got=[];const s=http.createServer((q,r)=>{r.setHeader('Access-Control-Allow-Origin','*');r.setHeader('Access-Control-Allow-Headers','*');if(q.method==='OPTIONS'){r.end();return}
  if(q.url==='/api/tags'){r.end(JSON.stringify({models:[{name:'qwen-test:1b'}]}));return}
  if(q.url==='/api/chat'){let b='';q.on('data',d=>b+=d);q.on('end',()=>{const body=JSON.parse(b);got.push(body);const last=body.messages.at(-1).content;let ans;
    if(!/Problems found/.test(last))ans={reply:'Two rooms and a desk.',commands:[{do:'room',name:'Loop A',x:120000,y:0,w:6000,h:4000},{do:'room',name:'Loop B',x:123000,y:0,w:6000,h:4000},{do:'place',code:'WS1470',x:140000,y:2000}]};
    else{const ids=[...last.matchAll(/WS1470 id (\w+)/g)].map(m=>m[1]);const rb=(last.match(/"Loop B" \(id (\w+)\)/)||[])[1];ans={reply:'Fixed.',commands:[{do:'move',ids:[rb],dx:3000,dy:0},{do:'move',ids:ids,dx:-18000,dy:0}]}}
    r.setHeader('Content-Type','application/x-ndjson');r.write(JSON.stringify({message:{role:'assistant',content:JSON.stringify(ans)},done:false})+'\n');r.end(JSON.stringify({done:true})+'\n')});return}
  r.statusCode=404;r.end()});s.listen(0,'127.0.0.1',()=>res({url:'http://127.0.0.1:'+s.address().port,got,close:()=>s.close()}))})}
/* an Ollama stand-in for the requirements workflow: reads a brief from the document, builds it one room short, then adds the missing room when the brief check comes back */
function fakeBrief(){return new Promise(res=>{const got=[];const s=http.createServer((q,r)=>{r.setHeader('Access-Control-Allow-Origin','*');r.setHeader('Access-Control-Allow-Headers','*');if(q.method==='OPTIONS'){r.end();return}
  if(q.url==='/api/tags'){r.end(JSON.stringify({models:[{name:'qwen-test:1b'}]}));return}
  if(q.url==='/api/chat'){let b='';q.on('data',d=>b+=d);q.on('end',()=>{const body=JSON.parse(b);got.push(body);const sys=body.messages[0].content,last=body.messages.at(-1).content;let ans;const X=300000;
    if(/You locate the rooms/.test(sys))ans={reply:'Two rooms side by side.',outline:[100,100,900,900],width_m:null,rooms:[{name:'Trace A',box:[100,100,498,900]},{name:'Trace B',box:[505,100,900,600]}],doors:[[500,400]]};
    else if(/traced from the user's drawing/.test(last))ans={reply:'Furnished.',commands:[]};
    else if(/turn them into a brief/.test(sys))ans={reply:'An office floor for 6 people with two meeting rooms.',brief:{title:'Test office',floors:1,rooms:[{name:'Zeta office',qty:1,area:40,seats:6,zone:'green'},{name:'Zeta huddle',qty:2,area:12,seats:null,zone:null}],notes:'Near the lift.'}};
    else if(/^StoreyBook ran your commands/.test(last))ans={reply:'Added the second meeting room.',commands:[{do:'room',name:'Zeta huddle 2',x:X+12000,y:0,w:4000,h:3200}]};
    else if(/Build what this brief asks for/.test(last))ans={reply:'Built the office.',commands:[{do:'room',name:'Zeta office',x:X,y:0,w:8000,h:6000,zone:'green'},{do:'array',code:'WS1470',x:X+1500,y:1500,rows:2,cols:3,dx:1600,dy:2600},{do:'room',name:'Zeta huddle 1',x:X+8000,y:0,w:4000,h:3200}]};
    else ans={reply:'Seen.',commands:[{do:'room',name:'From drawing',x:X+30000,y:0,w:3000,h:3000}]};
    r.setHeader('Content-Type','application/x-ndjson');r.write(JSON.stringify({message:{role:'assistant',content:JSON.stringify(ans)},done:false})+'\n');r.end(JSON.stringify({done:true})+'\n')});return}
  r.statusCode=404;r.end()});s.listen(0,'127.0.0.1',()=>res({url:'http://127.0.0.1:'+s.address().port,got,close:()=>s.close()}))})}
